import { __decorate } from "tslib";
import { Component } from '@angular/core';
let FornecedorComponent = class FornecedorComponent {
    constructor(fornecedorService, fb, dialog) {
        this.fornecedorService = fornecedorService;
        this.fb = fb;
        this.dialog = dialog;
        this.displayedColumns = ['nome', 'id'];
        this.dataSource = [];
        this.formSearch = this.fb.group({
            search: ['', [Validators.required]],
            submit: ['']
        });
    }
    async ngOnInit() {
        this.dataSource = await this.fornecedorService.findAll();
        console.log('data:', this.dataSource);
    }
    openCreateFornecedorDialog() {
        this.dialog.open(CreateFornecedorFormComponent, {
            width: '400px',
            height: '400px',
        });
    }
};
FornecedorComponent = __decorate([
    Component({
        selector: 'app-fornecedor',
        templateUrl: './fornecedor.component.html',
        styleUrls: ['./fornecedor.component.css']
    })
], FornecedorComponent);
export { FornecedorComponent };
